package sdkgen

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

const tsHeader = `// SPDX-License-Identifier: AGPL-3.0-only
// Code generated by internal/sdkgen from api/openapi.yaml. DO NOT EDIT.
// Regenerate with: make sdk
`

// tsTypeExpr writes a Type as a TypeScript type expression.
func tsTypeExpr(t *Type) string {
	var s string
	switch t.Kind {
	case KindString:
		s = "string"
	case KindInteger, KindNumber:
		s = "number"
	case KindBoolean:
		s = "boolean"
	case KindArray:
		inner := tsTypeExpr(t.Items)
		if strings.Contains(inner, " ") {
			inner = "(" + inner + ")"
		}
		s = inner + "[]"
	case KindMap:
		s = "Record<string, " + tsTypeExpr(t.Items) + ">"
	case KindRef:
		s = t.Ref
	case KindEnum:
		quoted := make([]string, len(t.Enum))
		for i, v := range t.Enum {
			quoted[i] = strconv.Quote(v)
		}
		s = strings.Join(quoted, " | ")
	case KindLiteral:
		s = strconv.Quote(t.Literal)
	case KindUnion:
		parts := make([]string, len(t.Variants))
		for i, v := range t.Variants {
			parts[i] = tsTypeExpr(v)
		}
		s = strings.Join(parts, " | ")
	default:
		s = "unknown"
	}
	if t.Nullable && s != "unknown" {
		s += " | null"
	}
	return s
}

// jsdoc writes text as a doc comment at the given indentation.
func jsdoc(b *strings.Builder, indent, text string) {
	text = strings.TrimSpace(strings.ReplaceAll(text, "*/", "*\\/"))
	if text == "" {
		return
	}
	lines := strings.Split(text, "\n")
	if len(lines) == 1 {
		fmt.Fprintf(b, "%s/** %s */\n", indent, lines[0])
		return
	}
	fmt.Fprintf(b, "%s/**\n", indent)
	for _, l := range lines {
		l = strings.TrimRight(l, " ")
		if l == "" {
			fmt.Fprintf(b, "%s *\n", indent)
		} else {
			fmt.Fprintf(b, "%s * %s\n", indent, l)
		}
	}
	fmt.Fprintf(b, "%s */\n", indent)
}

// TypeScriptTypes writes types.ts.
func TypeScriptTypes(api *API) []byte {
	var b strings.Builder
	b.WriteString(tsHeader)
	fmt.Fprintf(&b, "//\n// The types of the %s %s: one per schema of components/schemas,\n", api.Title, api.Version)
	b.WriteString("// and one per object a schema or an operation writes in place.\n")
	for _, n := range api.Types {
		b.WriteString("\n")
		jsdoc(&b, "", n.Doc)
		if n.Alias != nil {
			fmt.Fprintf(&b, "export type %s = %s;\n", n.Name, tsTypeExpr(n.Alias))
			continue
		}
		fmt.Fprintf(&b, "export interface %s {\n", n.Name)
		for _, f := range n.Fields {
			jsdoc(&b, "  ", f.Doc)
			opt := "?"
			if f.Required {
				opt = ""
			}
			fmt.Fprintf(&b, "  %s%s: %s;\n", tsKey(f.Name), opt, tsTypeExpr(f.Type))
		}
		b.WriteString("}\n")
	}
	return []byte(b.String())
}

func tsKey(name string) string {
	for _, r := range name {
		valid := r == '_' || r == '$' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9'
		if !valid {
			return strconv.Quote(name)
		}
	}
	return name
}

// opDoc is the doc comment of an operation's method.
func opDoc(op *Operation) string {
	var parts []string
	if op.Summary != "" {
		parts = append(parts, strings.TrimSuffix(op.Summary, ".")+".")
	}
	parts = append(parts, fmt.Sprintf("`%s %s`", strings.ToUpper(op.Method), op.Path))
	if op.Description != "" {
		parts = append(parts, op.Description)
	}
	if op.Auth == "user" {
		parts = append(parts, "Needs a user token (ohs_ut_) as the client's apiKey.")
	}
	return strings.Join(parts, "\n\n")
}

func tsParamsName(op *Operation) string { return pascal(op.ID) + "Params" }

// tsParams are the query and header parameters, passed as one object.
func tsParams(op *Operation) []*Param {
	return append(append([]*Param{}, op.QueryParams...), op.Headers...)
}

func anyRequired(ps []*Param) bool {
	for _, p := range ps {
		if p.Required {
			return true
		}
	}
	return false
}

func tsResult(op *Operation) string {
	switch op.Result {
	case ResultJSON:
		return tsTypeExpr(op.ResultType)
	case ResultBinary:
		return "Response"
	}
	return "void"
}

func tsPath(op *Operation) string {
	p := op.Path
	for _, pp := range op.PathParams {
		p = strings.ReplaceAll(p, "{"+pp.Name+"}", "${encode("+camel(pp.Ident)+")}")
	}
	if strings.Contains(p, "${") {
		return "`" + p + "`"
	}
	return strconv.Quote(p)
}

// TypeScriptClient writes client.ts.
func TypeScriptClient(api *API) []byte {
	var b strings.Builder
	b.WriteString(tsHeader)
	fmt.Fprintf(&b, "//\n// A client of the %s %s for Node.js 18 or later, on the global\n", api.Title, api.Version)
	b.WriteString("// fetch and with no dependency. One method per operation of the document.\n\n")

	used := map[string]bool{}
	for _, op := range api.Ops {
		collectRefs(op.ResultType, used)
		collectRefs(op.ItemType, used)
		if op.Body != nil {
			collectRefs(op.Body.Type, used)
		}
		for _, p := range append(append(append([]*Param{}, op.PathParams...), op.QueryParams...), op.Headers...) {
			collectRefs(p.Type, used)
		}
	}
	used["Problem"] = true // read by OhsError
	names := make([]string, 0, len(used))
	for n := range used {
		names = append(names, n)
	}
	sort.Strings(names)
	b.WriteString("import type {\n")
	for _, n := range names {
		fmt.Fprintf(&b, "  %s,\n", n)
	}
	b.WriteString("} from \"./types.ts\";\n\n")
	b.WriteString(tsRuntime)

	for _, op := range api.Ops {
		ps := tsParams(op)
		if len(ps) == 0 {
			continue
		}
		b.WriteString("\n")
		jsdoc(&b, "", fmt.Sprintf("Query and header parameters of {@link OpenHealthSync.%s}.", op.ID))
		fmt.Fprintf(&b, "export interface %s {\n", tsParamsName(op))
		for _, p := range ps {
			doc := p.Doc
			if p.In == "header" {
				doc = strings.TrimSpace("Sent as the " + p.Name + " header. " + doc)
			}
			jsdoc(&b, "  ", doc)
			opt := "?"
			if p.Required {
				opt = ""
			}
			fmt.Fprintf(&b, "  %s%s: %s;\n", camel(p.Ident), opt, tsTypeExpr(p.Type))
		}
		b.WriteString("}\n")
	}

	b.WriteString(tsClassHead)
	for _, op := range api.Ops {
		b.WriteString("\n")
		tsMethod(&b, op)
		if op.Paged {
			b.WriteString("\n")
			tsIterator(&b, op)
		}
	}
	b.WriteString(tsClassTail)
	return []byte(b.String())
}

func collectRefs(t *Type, into map[string]bool) {
	if t == nil {
		return
	}
	if t.Kind == KindRef {
		into[t.Ref] = true
	}
	collectRefs(t.Items, into)
	for _, v := range t.Variants {
		collectRefs(v, into)
	}
}

// tsArgs is the argument list of a method, without options.
func tsArgs(op *Operation, iter bool) []string {
	var args []string
	for _, p := range op.PathParams {
		args = append(args, camel(p.Ident)+": "+tsTypeExpr(p.Type))
	}
	if op.Body != nil {
		t := "Uint8Array | ArrayBuffer | Blob"
		if !op.Body.Binary {
			t = tsTypeExpr(op.Body.Type)
		}
		if op.Body.Required {
			args = append(args, "body: "+t)
		} else {
			args = append(args, "body?: "+t)
		}
	}
	if ps := tsParams(op); len(ps) > 0 {
		t := tsParamsName(op)
		if iter {
			t = fmt.Sprintf("Omit<%s, \"cursor\">", t)
		}
		if anyRequired(ps) {
			args = append(args, "params: "+t)
		} else {
			args = append(args, "params: "+t+" = {}")
		}
	}
	opts := "options?: RequestOptions"
	if op.Idempotent {
		opts = "options?: IdempotentRequestOptions"
	}
	return append(args, opts)
}

func tsSignature(b *strings.Builder, name string, args []string, ret string) {
	one := fmt.Sprintf("  %s(%s): %s {\n", name, strings.Join(args, ", "), ret)
	if len(one) <= 101 {
		b.WriteString(one)
		return
	}
	fmt.Fprintf(b, "  %s(\n", name)
	for _, a := range args {
		fmt.Fprintf(b, "    %s,\n", a)
	}
	fmt.Fprintf(b, "  ): %s {\n", ret)
}

func tsMethod(b *strings.Builder, op *Operation) {
	jsdoc(b, "  ", opDoc(op))
	tsSignature(b, op.ID, tsArgs(op, false), "Promise<"+tsResult(op)+">")
	expect := map[string]string{ResultJSON: "json", ResultNone: "none", ResultBinary: "response"}[op.Result]
	fmt.Fprintf(b, "    return this.#request<%s>({\n", tsResult(op))
	fmt.Fprintf(b, "      method: %q,\n", strings.ToUpper(op.Method))
	fmt.Fprintf(b, "      path: %s,\n", tsPath(op))
	if len(op.QueryParams) > 0 {
		b.WriteString("      query: {\n")
		for _, p := range op.QueryParams {
			fmt.Fprintf(b, "        %s: params.%s,\n", tsKey(p.Name), camel(p.Ident))
		}
		b.WriteString("      },\n")
	}
	if len(op.Headers) > 0 {
		b.WriteString("      headers: {\n")
		for _, p := range op.Headers {
			fmt.Fprintf(b, "        %s: params.%s,\n", strconv.Quote(p.Name), camel(p.Ident))
		}
		b.WriteString("      },\n")
	}
	if op.Body != nil {
		if op.Body.Binary {
			b.WriteString("      body,\n")
			fmt.Fprintf(b, "      contentType: %q,\n", op.Body.ContentType)
		} else {
			b.WriteString("      json: body,\n")
		}
	}
	fmt.Fprintf(b, "      expect: %q,\n", expect)
	b.WriteString("      options,\n")
	b.WriteString("    });\n")
	b.WriteString("  }\n")
}

func tsIterator(b *strings.Builder, op *Operation) {
	jsdoc(b, "  ", fmt.Sprintf("Every item of {@link OpenHealthSync.%s}, page after page, following `next_cursor`.", op.ID))
	tsSignature(b, IterName(op.ID), tsArgs(op, true), "AsyncGenerator<"+tsTypeExpr(op.ItemType)+">")
	var call []string
	for _, p := range op.PathParams {
		call = append(call, camel(p.Ident))
	}
	call = append(call, "{ ...params, cursor }", "options")
	fmt.Fprintf(b, "    return paginate((cursor) => this.%s(%s));\n", op.ID, strings.Join(call, ", "))
	b.WriteString("  }\n")
}

const tsRuntime = `export interface ClientOptions {
  /** Base URL of the instance, for example https://health.example.com. */
  baseUrl: string;
  /** Tenant API key (ohs_sk_...), or a user token (ohs_ut_...) for the user routes. */
  apiKey: string;
  /** The fetch to call; the global fetch when absent. */
  fetch?: typeof fetch;
}

export interface RequestOptions {
  /** Headers added to this request. */
  headers?: Record<string, string>;
  /** Aborts the request. */
  signal?: AbortSignal;
}

export interface IdempotentRequestOptions extends RequestOptions {
  /**
   * Sent as Idempotency-Key (1 to 255 characters): a retry with the same key and the same
   * request within 24 hours gets the first response back.
   */
  idempotencyKey?: string;
}

/** An error answer of the API, read from its application/problem+json body. */
export class OhsError extends Error {
  /** The HTTP status code. */
  readonly status: number;
  /** The problem's title, or the status text when the body is not a problem. */
  readonly title: string;
  /** The problem's detail, when it has one. */
  readonly detail?: string;
  /** The problem's type URI. */
  readonly type?: string;
  /** The X-Request-Id of the response, to quote when reporting the error. */
  readonly requestId?: string;
  /** The parsed body (a Problem), or its text when it is not JSON. */
  readonly body: unknown;

  constructor(
    status: number,
    title: string,
    init: { detail?: string; type?: string; requestId?: string; body?: unknown } = {},
  ) {
    super(init.detail ? ` + "`${status} ${title}: ${init.detail}`" + ` : ` + "`${status} ${title}`" + `);
    this.name = "OhsError";
    this.status = status;
    this.title = title;
    this.detail = init.detail;
    this.type = init.type;
    this.requestId = init.requestId;
    this.body = init.body;
  }

  /** Reads an error response. */
  static async fromResponse(res: Response): Promise<OhsError> {
    const text = await res.text();
    let body: unknown = text;
    try {
      body = JSON.parse(text);
    } catch {
      // Not JSON: keep the text.
    }
    const problem = (typeof body === "object" && body !== null ? body : {}) as Partial<Problem>;
    return new OhsError(res.status, problem.title ?? res.statusText, {
      detail: problem.detail,
      type: problem.type,
      requestId: res.headers.get("X-Request-Id") ?? problem.request_id,
      body,
    });
  }
}

/** One page of a list. */
export interface Page<T> {
  data: T[];
  next_cursor: string | null;
}

/** Yields every item of a list, fetching page after page until next_cursor is null. */
export async function* paginate<T>(fetchPage: (cursor: string | undefined) => Promise<Page<T>>): AsyncGenerator<T> {
  let cursor: string | undefined;
  do {
    const page = await fetchPage(cursor);
    yield* page.data;
    cursor = page.next_cursor ?? undefined;
  } while (cursor);
}

function encode(value: string | number): string {
  return encodeURIComponent(String(value));
}

interface Call {
  method: string;
  path: string;
  query?: Record<string, string | number | boolean | undefined>;
  headers?: Record<string, string | number | undefined>;
  json?: unknown;
  body?: Uint8Array | ArrayBuffer | Blob;
  contentType?: string;
  expect: "json" | "none" | "response";
  options?: IdempotentRequestOptions;
}
`

const tsClassHead = `
/**
 * A client of the Open Health Sync API.
 *
 *     const ohs = new OpenHealthSync({ baseUrl: "https://health.example.com", apiKey: process.env.OHS_API_KEY! });
 *     const user = await ohs.createUser({ external_ref: "customer-42" });
 */
export class OpenHealthSync {
  readonly baseUrl: string;
  readonly #apiKey: string;
  readonly #fetch: typeof fetch;

  constructor(options: ClientOptions) {
    if (!options.baseUrl) throw new TypeError("OpenHealthSync: baseUrl is required");
    if (!options.apiKey) throw new TypeError("OpenHealthSync: apiKey is required");
    this.baseUrl = options.baseUrl.replace(/\/+$/, "");
    this.#apiKey = options.apiKey;
    this.#fetch = options.fetch ?? ((input, init) => fetch(input, init));
  }

  async #request<T>(call: Call): Promise<T> {
    const url = new URL(this.baseUrl + call.path);
    for (const [name, value] of Object.entries(call.query ?? {})) {
      if (value !== undefined && value !== null) url.searchParams.set(name, String(value));
    }
    const headers: Record<string, string> = { Authorization: ` + "`Bearer ${this.#apiKey}`" + ` };
    if (call.expect === "json") headers.Accept = "application/json";
    for (const [name, value] of Object.entries(call.headers ?? {})) {
      if (value !== undefined && value !== null) headers[name] = String(value);
    }
    let body: string | Uint8Array | ArrayBuffer | Blob | undefined;
    if (call.json !== undefined) {
      body = JSON.stringify(call.json);
      headers["Content-Type"] = "application/json";
    } else if (call.body !== undefined) {
      body = call.body;
      headers["Content-Type"] = call.contentType ?? "application/octet-stream";
    }
    if (call.options?.idempotencyKey) headers["Idempotency-Key"] = call.options.idempotencyKey;
    Object.assign(headers, call.options?.headers);

    const res = await this.#fetch(url, { method: call.method, headers, body, signal: call.options?.signal });
    if (!res.ok) throw await OhsError.fromResponse(res);
    if (call.expect === "response") return res as T;
    if (call.expect === "none") {
      await res.body?.cancel();
      return undefined as T;
    }
    return (await res.json()) as T;
  }
`

const tsClassTail = "}\n"
